import {createCharacterModel} from './character-model.js';
import {tacticsPanel,counterReminder} from './tactics.js';
import {accountRoutes,accountPage,wireAccount} from './account.js';
import {guides,extraCharacters} from './content.js';
import {guidePage,wireGuide,rosterPage} from './guide.js';
import {enigmesPage,wireEnigmes,enigmaMeta} from './enigmes.js';
import {solvedCount} from './progress.js';
import {createMotion} from './trajectory.js';
const characterSymbols={"raijin":"M14 2 5 14h6l-1 8 9-13h-6z","keplar":"M3 12c0-7 18-7 18 0s-18 7-18 0M12 3c7 0 7 18 0 18s-7-18 0-18","andaris":"M12 2 3 12l9 10 9-10zM7 12h10M12 7v10","pandore":"M5 4c0 14 14 14 14 0M5 20c0-14 14-14 14 0"};
import {createAmbient} from './ambient.js';
import {characters,fragments,chapters} from './data.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
Object.assign(characterSymbols,{obsidia:'M12 2v20M4 6l5 6-5 6M20 6l-5 6 5 6',aurion:'M12 2v4M12 18v4M2 12h4M18 12h4M5 5l3 3M16 16l3 3M19 5l-3 3M8 16l-3 3M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8',vaalbara:'M12 3 3 20h18zM12 9v7M9 16h6',chronis:'M5 3h14M5 21h14M7 3c0 9 10 9 10 18M17 3c0 9-10 9-10 18',magnora:'M5 4v9a7 7 0 0 0 14 0V4h-4v9a3 3 0 0 1-6 0V4z'});
for(const [key,c] of Object.entries(extraCharacters))characters[key]={...c,position:'0%',pending:true,editorial:'Une identité posée. Un kit encore à concevoir.',state:'Identité posée · kit à définir',strength:'La fonction de '+c.role+' guide sa conception. Ses forces précises dépendront de son futur kit.',weakness:'Les réponses mécaniques, vulnérabilités et synergies restent à définir.',abilities:[['Passif','À concevoir','Le Passif reste à définir.'],['Sort','À concevoir','Le Sort reste à définir et devra conserver une utilité depuis la zone supérieure.'],['Ultime','À concevoir','L’Ultime reste à définir.']]};
const app=$('#app'),keys=Object.keys(characters);
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,override=false;
try{const saved=localStorage.getItem('ora-reduce-motion');if(saved!==null){reduced=saved==='true';override=true;}}catch{}
function motion(){document.documentElement.classList.toggle('reduced',reduced);document.documentElement.classList.toggle('motion-enabled',!reduced);$('#motion').setAttribute('aria-pressed',String(reduced));$('#motion').setAttribute('aria-label',reduced?'Activer les animations':'Réduire les animations');$('#motion span').textContent=reduced?'▷':'Ⅱ';if(reduced){app.style.removeProperty('--mx');app.style.removeProperty('--my');}document.dispatchEvent(new Event('ora-motion-change'));}
motion();$('#motion').onclick=()=>{reduced=!reduced;override=true;motion();try{localStorage.setItem('ora-reduce-motion',String(reduced));}catch{}};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(!override){reduced=e.matches;motion();}});
function closeMenu(){$('#mobile-nav').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');$('#menu-button').setAttribute('aria-label','Ouvrir la navigation');}
$('#menu-button').onclick=()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-button').setAttribute('aria-expanded',String(open));$('#menu-button').setAttribute('aria-label',open?'Fermer la navigation':'Ouvrir la navigation');};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){closeMenu();$('#menu-button').focus();}});
matchMedia('(min-width: 1025px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
const effects=createMotion(()=>reduced);
function updateSeals(){const n=solvedCount();$$('.seal-count').forEach(el=>el.textContent=`${n}/9`);$$('.home-enigma').forEach(el=>{el.style.setProperty('--p',n/9);$('strong',el).textContent=n===9?'L’archipel est relié':n?`${n} îlot${n>1?'s':''} relié${n>1?'s':''} sur 9`:'Neuf sceaux à briser';});}
document.addEventListener('ora-progress',updateSeals);
$$('dialog').forEach(dialog=>{$('.close-dialog',dialog).onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});});
$('#about-button').onclick=()=>$('#info-dialog').showModal();
const scene=()=>'<div class="world" aria-hidden="true"></div><div class="atmosphere" aria-hidden="true"></div><div class="dust" aria-hidden="true"></div>';
const arrow='<span aria-hidden="true">↗</span>';
function home(){return `<section class="screen crossroads" aria-labelledby="screen-title">${scene()}<div class="orbit" aria-hidden="true"><i></i><i></i><span>ORA</span></div><div class="home-title"><p class="eyebrow">PAR-DELÀ LES ÎLOTS</p><h1 id="screen-title" tabindex="-1">ORA</h1><p>Les mondes se rencontrent.<br>Choisissez votre trajectoire.</p><a class="home-game-link" href="/jeu/">DÉCOUVRIR LE JEU ↗</a></div><nav class="portals" aria-label="Choisir une destination"><a class="portal portal-world" href="/univers/"><span class="portal-glyph" aria-hidden="true">⌖</span><span class="portal-copy"><small>01 / EXPLORER</small><strong>Les mondes <br>suspendus</strong><em>Entrer dans l’atlas ${arrow}</em></span></a><a class="portal portal-people" href="/personnages/"><span class="portal-glyph" aria-hidden="true">✳</span><span class="portal-copy"><small>02 / RENCONTRER</small><strong>Les forces <br>en présence</strong><em>Choisir un personnage ${arrow}</em></span></a><a class="portal portal-story" href="/histoire/"><span class="portal-glyph" aria-hidden="true">◈</span><span class="portal-copy"><small>03 / DÉCOUVRIR</small><strong>Les premières <br>chroniques</strong><em>Ouvrir l’histoire ${arrow}</em></span></a></nav><a class="home-enigma" href="/enigmes/"><span class="enigma-ring" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3 21 12 12 21 3 12Z M12 8 16 12 12 16 8 12Z"/></svg></span><span><small>04 / DÉCHIFFRER · L’ARCHIPEL SCELLÉ</small><strong>Neuf sceaux à briser</strong></span><span class="enigma-arrow" aria-hidden="true">↗</span></a><span class="scene-note">UNIVERS D’ORA · SPORT FUTURISTE / ÉNERGIE ANCIENNE</span></section>`;}
let fragment=0,zoom=1,pan={x:0,y:0};
function atlas(){return `<section class="screen atlas-screen" aria-labelledby="screen-title"><div class="atlas-viewport" aria-label="Carte illustrative à déplacer" tabindex="0"><div class="map-surface">${scene()}<div class="map-grid" aria-hidden="true"></div><svg class="map-connections" viewBox="0 0 1000 700" preserveAspectRatio="none" aria-hidden="true"><path d="M220 280 Q460 100 570 220 T820 430"/></svg><div class="map-nodes" role="tablist" aria-label="Repères de l’atlas">${['Les îlots','Les civilisations','L’ORA'].map((label,i)=>`<button class="map-node node-${i}" data-fragment="${i}" id="fragment-tab-${i}" role="tab" aria-controls="fragment-panel" aria-selected="${i===fragment}" tabindex="${i===fragment?0:-1}"><span class="node-orbit"><span aria-hidden="true">◇</span></span><strong>${label}</strong></button>`).join('')}</div></div></div><div class="atlas-title"><p class="eyebrow">01 / EXPLORER</p><h1 id="screen-title" tabindex="-1">L’atlas<br><em>des fragments.</em></h1><span>Géographie illustrative</span></div><div class="map-tools" aria-label="Contrôles de la carte"><button id="zoom-in" aria-label="Agrandir la carte">+</button><button id="zoom-out" aria-label="Réduire la carte">−</button><button id="reset-map" aria-label="Recentrer la carte">⌖</button></div><article class="fragment-panel" id="fragment-panel" role="tabpanel" aria-labelledby="fragment-tab-${fragment}" tabindex="0"><p class="eyebrow" id="fragment-kicker"></p><h2 id="fragment-title"></h2><p id="fragment-text"></p><a id="fragment-link" class="atlas-reading-link" href="/univers/civilisations/">EXPLORER CE FRAGMENT ↗</a><button class="text-action" id="next-fragment">REPÈRE SUIVANT <span aria-hidden="true">→</span></button></article><span class="map-help">GLISSER POUR EXPLORER <span aria-hidden="true">↔</span></span></section>`;}
function selectFragment(index){fragment=index;$('#fragment-link').href=index===2?'/univers/ora/':'/univers/civilisations/';const buttons=$$('[data-fragment]');buttons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});['kicker','title','text'].forEach((field,i)=>$(`#fragment-${field}`).textContent=fragments[index][i]);$('#fragment-panel').setAttribute('aria-labelledby',`fragment-tab-${index}`);pulse($('#fragment-panel'));}
function mapTransform(){const el=$('.map-surface');if(el)el.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;$('#zoom-in').disabled=zoom>=1.6;$('#zoom-out').disabled=zoom<=1;}
function wireAtlas(){selectFragment(fragment);const buttons=$$('[data-fragment]');buttons.forEach((b,i)=>b.onclick=()=>selectFragment(i));arrowTabs(buttons,selectFragment);$('#next-fragment').onclick=()=>selectFragment((fragment+1)%3);$('#zoom-in').onclick=()=>{zoom=Math.min(1.6,+(zoom+.2).toFixed(1));mapTransform();};$('#zoom-out').onclick=()=>{zoom=Math.max(1,+(zoom-.2).toFixed(1));mapTransform();};$('#reset-map').onclick=()=>{zoom=1;pan={x:0,y:0};mapTransform();};mapTransform();const view=$('.atlas-viewport');let drag=null;view.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};view.setPointerCapture(e.pointerId);view.classList.add('dragging');});view.addEventListener('pointermove',e=>{if(!drag)return;pan.x=Math.max(-innerWidth*.16,Math.min(innerWidth*.16,drag.px+e.clientX-drag.x));pan.y=Math.max(-90,Math.min(90,drag.py+e.clientY-drag.y));mapTransform();});const stop=()=>{drag=null;view.classList.remove('dragging');};view.addEventListener('pointerup',stop);view.addEventListener('pointercancel',stop);view.addEventListener('keydown',e=>{if(e.target!==view)return;const moves={ArrowLeft:[-25,0],ArrowRight:[25,0],ArrowUp:[0,-25],ArrowDown:[0,25]};if(moves[e.key]){e.preventDefault();pan.x=Math.max(-innerWidth*.16,Math.min(innerWidth*.16,pan.x+moves[e.key][0]));pan.y=Math.max(-90,Math.min(90,pan.y+moves[e.key][1]));mapTransform();}});}
let detail='identity',selectedCharacter='raijin';
function character(key){const c=characters[key];selectedCharacter=key;return `<section class="screen character-screen" style="--character-color:${c.color};--portrait:${c.position}" aria-labelledby="screen-title"><div class="character-backdrop" aria-hidden="true"></div><span class="character-watermark" aria-hidden="true">${c.name.toUpperCase()}</span><div class="character-model" data-state="loading"><canvas tabindex="0" role="img" aria-label="Étude 3D de ${c.name}. Faites glisser ou utilisez les flèches gauche et droite pour tourner."></canvas><div class="model-caption"><span class="model-status" role="status">Chargement du personnage…</span><small>Glisser pour tourner · ← → au clavier</small><button data-model-reset aria-label="Recentrer le personnage">RECENTRER ↺</button></div></div><div class="character-haze" aria-hidden="true"></div><div class="character-copy"><p class="eyebrow">02 / ${c.role.toUpperCase()} <span class="type-label">${c.type.toUpperCase()}</span></p><h1 id="screen-title" tabindex="-1">${c.name}</h1><p class="character-tagline">${c.tagline}</p><div class="character-tabs" role="tablist" aria-label="Fiche de ${c.name}"><button role="tab" id="identity-tab" aria-selected="${detail==='identity'}" aria-controls="identity-panel" tabindex="${detail==='identity'?0:-1}" data-detail="identity">Identité</button><button role="tab" id="abilities-tab" aria-selected="${detail==='abilities'}" aria-controls="abilities-panel" tabindex="${detail==='abilities'?0:-1}" data-detail="abilities">Aptitudes</button><button role="tab" id="tactics-tab" aria-selected="${detail==='tactics'}" aria-controls="tactics-panel" tabindex="${detail==='tactics'?0:-1}" data-detail="tactics">Contres</button><button role="tab" id="lore-tab" aria-selected="${detail==='lore'}" aria-controls="lore-panel" tabindex="${detail==='lore'?0:-1}" data-detail="lore">Histoire</button></div><div class="character-reading"><article role="tabpanel" id="identity-panel" aria-labelledby="identity-tab" tabindex="0" ${detail!=='identity'?'hidden':''}><p class="content-state">${c.state}</p><p>${c.identity}</p><blockquote>${c.editorial}</blockquote>${counterReminder(key)}<div class="strength-grid"><div><h3>Sa force</h3><p>${c.strength}</p></div><div><h3>Sa faille</h3><p>${c.weakness}</p></div></div></article><article role="tabpanel" id="abilities-panel" aria-labelledby="abilities-tab" tabindex="0" ${detail!=='abilities'?'hidden':''}>${c.abilities.map(([kind,title,text],i)=>`<details class="ability" ${i===0?'open':''}><summary><span>${kind}</span><strong>${title}</strong><i aria-hidden="true">+</i></summary><p>${text}</p></details>`).join('')}<p class="note">${c.state}. Concepts de capacités, pas une démonstration en jeu.</p></article><article role="tabpanel" id="tactics-panel" aria-labelledby="tactics-tab" tabindex="0" ${detail!=='tactics'?'hidden':''}>${tacticsPanel(key)}</article><article role="tabpanel" id="lore-panel" aria-labelledby="lore-tab" tabindex="0" ${detail!=='lore'?'hidden':''}><span class="eyebrow">UNE PAGE ENCORE OUVERTE</span><h2>D’où vient ${c.name} ?</h2><p>Son origine, sa ville natale et sa biographie restent à écrire. Son identité actuelle se construit autour de ${c.type.toLowerCase()} et du rôle de ${c.role.toLowerCase()}.</p><a href="/histoire/" class="text-action">DÉCOUVRIR L’HISTOIRE DU MONDE ${arrow}</a></article></div></div><div class="character-dock"><div class="dock-intro"><span class="eyebrow">CHOISIR UNE TRAJECTOIRE</span><span>0${keys.indexOf(key)+1} <i>/ 09</i></span></div><nav class="character-select" aria-label="Choisir un personnage">${keys.filter(k=>characters[k].role===c.role).map(k=>`<a href="/personnages/${k}/" data-character="${k}" class="portrait-choice ${k===key?'selected':''}" style="--portrait:${characters[k].position};--character-color:${characters[k].color}" ${k===key?'aria-current="page"':''}><span>${characters[k].name}</span></a>`).join('')}</nav><a href="/personnages/roster/" class="roster-button"><span aria-hidden="true">⊞</span> LES 9 PERSONNAGES</a></div></section>`;}
function selectDetail(value){detail=value;$$('[data-detail]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.detail===value));b.tabIndex=b.dataset.detail===value?0:-1;});['identity','abilities','tactics','lore'].forEach(id=>$(`#${id}-panel`).hidden=id!==value);pulse($(`#${value}-panel`));$('.character-reading').scrollTop=0;}
function wireCharacter(){$('[data-open-tactics]').onclick=()=>{selectDetail('tactics');$('#tactics-tab').focus();};const buttons=$$('[data-detail]');buttons.forEach(b=>b.onclick=()=>selectDetail(b.dataset.detail));arrowTabs(buttons,i=>selectDetail(buttons[i].dataset.detail));}
let chapter=0;
function story(){return `<section class="screen story-screen" data-chapter="${chapter}" aria-labelledby="screen-title">${scene()}<div class="story-counter" aria-hidden="true">${chapters[chapter][0]}</div><div class="story-layout"><p class="eyebrow">03 / LES CHRONIQUES</p><div class="story-paper" role="tabpanel" aria-labelledby="story-tab-${chapter}" id="story-panel" tabindex="0"><p class="eyebrow story-era">${chapters[chapter][1]}</p><h1 id="screen-title" tabindex="-1">${chapters[chapter][2]}</h1><p class="story-text">${chapters[chapter][3]}</p><span class="story-status">${chapters[chapter][4]}</span></div><div class="story-paging"><button id="previous-chapter" aria-label="Chapitre précédent" ${chapter===0?'disabled':''}>←</button><span>0${chapter+1} <i>/ 03</i></span><button id="next-chapter" aria-label="Chapitre suivant" ${chapter===2?'disabled':''}>→</button></div></div><div class="timeline" role="tablist" aria-label="Chapitres de l’histoire">${['L’isolement','La reconnexion','L’énergie ancienne'].map((name,i)=>`<button role="tab" id="story-tab-${i}" data-chapter="${i}" aria-controls="story-panel" aria-selected="${i===chapter}" tabindex="${i===chapter?0:-1}"><span>0${i+1}</span><strong>${name}</strong><i aria-hidden="true"></i></button>`).join('')}</div><span class="scene-note">LES PREMIÈRES PAGES DU MONDE D’ORA</span></section>`;}
function selectChapter(index){chapter=index;const c=chapters[index];$('.story-screen').dataset.chapter=index;$('.story-counter').textContent=c[0];$('.story-era').textContent=c[1];$('#screen-title').textContent=c[2];$('.story-text').textContent=c[3];$('.story-status').textContent=c[4];$('#story-panel').setAttribute('aria-labelledby',`story-tab-${index}`);$('.story-paging>span').innerHTML=`0${index+1} <i>/ 03</i>`;$('#previous-chapter').disabled=index===0;$('#next-chapter').disabled=index===2;$$('button[data-chapter]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});pulse($('#story-panel'));history.replaceState(null,'',`/histoire/?chapitre=${index+1}`);document.title=`${c[2]} — Chroniques | ORA`;}
function wireStory(){const buttons=$$('button[data-chapter]');buttons.forEach((b,i)=>b.onclick=()=>selectChapter(i));arrowTabs(buttons,selectChapter);$('#previous-chapter').onclick=()=>selectChapter(Math.max(0,chapter-1));$('#next-chapter').onclick=()=>selectChapter(Math.min(2,chapter+1));}
function arrowTabs(buttons,select){buttons.forEach((b,i)=>b.addEventListener('keydown',e=>{let target;if(e.key==='ArrowRight')target=(i+1)%buttons.length;else if(e.key==='ArrowLeft')target=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')target=0;else if(e.key==='End')target=buttons.length-1;else return;e.preventDefault();select(target);buttons[target].focus();}));}
function pulse(el){if(reduced)return;el.classList.remove('reenter');void el.offsetWidth;el.classList.add('reenter');}
function pathName(){return location.pathname.replace(/\/+$/,'')||'/';}
let stopAmbient=()=>{};
function render(focus=false,origin=null){stopAmbient();let cleanup=null;closeMenu();$$('dialog[open]').forEach(d=>d.close());const path=pathName();let kind='home';if(accountRoutes.includes(path)){kind='account';app.innerHTML=accountPage();wireAccount();document.title='Espace joueur | ORA';}else if(guides[path]){kind='guide';app.innerHTML=guidePage(path);wireGuide();document.title=guides[path].label+' | ORA';}else if(path==='/personnages/roster'){kind='roster';app.innerHTML=rosterPage(characters,characterSymbols);document.title='Les neuf personnages | ORA';}else if(path==='/univers'){kind='atlas';app.innerHTML=atlas();wireAtlas();document.title='L’atlas des fragments | ORA';}else if(path==='/personnages'||(path.startsWith('/personnages/')&&Object.hasOwn(characters,path.split('/')[2]))){kind='characters';const key=path.split('/')[2]||selectedCharacter;app.innerHTML=character(key);wireCharacter();document.title=`${characters[key].name} — Personnages | ORA`;}else if(path==='/histoire'){kind='story';const value=Number(new URLSearchParams(location.search).get('chapitre'));chapter=Number.isInteger(value)&&value>=1&&value<=3?value-1:0;app.innerHTML=story();wireStory();document.title='Les chroniques | ORA';}else if(path==='/enigmes'){kind='enigmes';app.innerHTML=enigmesPage(characters,characterSymbols);cleanup=wireEnigmes(characters,characterSymbols,effects,()=>render());document.title=enigmaMeta(characters)[0];}else{app.innerHTML=home();document.title='ORA — Par-delà les îlots';}stopAmbient=cleanup||(kind==='characters'?createCharacterModel($('.character-model'),selectedCharacter,characters[selectedCharacter].color,()=>reduced):app.querySelector('.ora-diagram')?()=>{}:createAmbient(app.firstElementChild,()=>reduced));document.body.dataset.screen=kind;$('#location-label').textContent=({home:'CHOISISSEZ VOTRE TRAJECTOIRE',atlas:'ATLAS / 3 FRAGMENTS',characters:'PERSONNAGES / '+characters[selectedCharacter].name.toUpperCase(),story:'CHRONIQUES / ORIGINES',guide:guides[path]?.label.toUpperCase(),roster:'PERSONNAGES / LES NEUF IDENTITÉS',account:'ESPACE JOUEUR / ORA',enigmes:enigmaMeta(characters)[1]})[kind];$$('.shell-nav a,.player-chip').forEach(a=>{if(path.startsWith(a.getAttribute('href').replace(/\/$/,'')))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});app.scrollTop=0;if(focus)$('#screen-title').focus({preventScroll:true});
updateSeals();effects.placeBall();if(origin&&!reduced){effects.launch(origin.x,origin.y);if(origin.reveal){const screen=app.firstElementChild;screen.style.setProperty('--reveal-x',`${origin.x}px`);screen.style.setProperty('--reveal-y',`${origin.y}px`);screen.classList.add('reveal');}}}
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey||a.target)return;const url=new URL(a.href);if(url.origin!==location.origin||url.hash)return;const box=a.getBoundingClientRect(),reveal=url.pathname!==location.pathname;e.preventDefault();history.pushState(null,'',url.pathname+url.search);render(true,{x:e.detail?e.clientX:box.left+box.width/2,y:e.detail?e.clientY:box.top+box.height/2,reveal});});
addEventListener('popstate',()=>render(true,{x:innerWidth/2,y:innerHeight/2,reveal:true}));
function migrateHash(){const legacy=location.hash;if(!legacy)return;const map={'#univers':'/univers/','#personnages':'/personnages/','#histoire':'/histoire/','#accueil':'/'};let path=map[legacy];const match=legacy.match(/^#personnage\/(raijin|keplar|andaris|pandore)$/);if(match)path=`/personnages/${match[1]}/`;if(path){history.replaceState(null,'',path);render();}}
render();migrateHash();addEventListener('hashchange',migrateHash);
let pointerFrame=false;app.addEventListener('pointermove',e=>{if(reduced||e.pointerType==='touch'||document.body.dataset.screen!=='home'||pointerFrame)return;pointerFrame=true;requestAnimationFrame(()=>{app.style.setProperty('--mx',`${(e.clientX/innerWidth-.5)*12}px`);app.style.setProperty('--my',`${(e.clientY/innerHeight-.5)*8}px`);pointerFrame=false;});});


